            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Душа дитини — це чистий аркуш, на якому кожен може написати що завгодно. І тільки від нас залежить, що буде написано на цій сторінці.", Author = "Олесь Гончар" },
