            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Письменник — це не той, хто пише, а той, хто живе своїм словом, хто вкладає в нього душу і серце.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Істина — це не те, що говорять, а те, що відчувають. І кожен повинен знайти свою істину.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Справжня краса — це не зовнішність, а внутрішній світ людини, її доброта і мудрість.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Найбільше багатство — це знання. Вони збагачують душу і роблять нас сильнішими.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Історія — це не просто минуле, це урок для майбутнього. І хто не вчить уроків історії, той приречений на повторення помилок.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Любов — це найсильніша сила у світі. Вона здатна творити дива і змінювати життя.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Кожен з нас — це цеглинка у фундаменті нації. І від кожного залежить, наскільки міцною буде наша держава.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Не бійтеся мріяти. Мрії — це крила, які допомагають нам злетіти над буденністю.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Мужність — це не відсутність страху, а здатність подолати його.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Слово має силу. І його треба вживати розумно, щоб воно лікувало, а не ранило.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Праця — це запорука щастя. І тільки в праці людина знаходить себе.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Душа — це дзеркало, в якому відбивається вся наша сутність. І тільки від нас залежить, чи буде воно чистим.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Народ, який забуває своє коріння, втрачає майбутнє.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Мистецтво — це мова душі. Воно здатне передати найглибші почуття і думки.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Життя — це книга. І кожен день — це нова сторінка, яку ми пишемо своїми вчинками.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Правда — це світло, яке висвітлює шлях. І тільки йдучи за ним, ми можемо знайти істину.", Author = "Олесь Гончар" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Олесь_Гончар", Text = "Свобода — це не вседозволеність, а відповідальність за свої дії.", Author = "Олесь Гончар" },
